from taf.gnb.oam.coam.vdu.schemas.fh.set_ret_configuration_response import Operation, SchemaField, SchemaObject


class WeightDataWeight(SchemaObject):
    phase = SchemaField(name='phase')
    group_id = SchemaField(name='groupId')
    amplitude = SchemaField(name='amplitude')
    port_index = SchemaField(name='portIndex')

    def __init__(self, phase, group_id, amplitude, port_index):
        self.phase = phase
        self.group_id = group_id
        self.amplitude = amplitude
        self.port_index = port_index

        super(WeightDataWeight, self).__init__()


class WeightData(SchemaObject):
    weight = SchemaField(name='weight', many=True, klass=WeightDataWeight)

    def __init__(self, weight):
        self.weight = weight

        super(WeightData, self).__init__()


class GetWeightDataResponse(Operation):
    weight_data = SchemaField(name='weightData', optional=True, klass=WeightData)

    def __init__(self, id, status, detailed_statuses, error_message, error_code, weight_data):
        self.id = id
        self.status = status
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message
        self.error_code = error_code
        self.weight_data = weight_data

        super(GetWeightDataResponse, self).__init__(id, status, detailed_statuses, error_message, error_code)
